import base64
import hashlib
import os
import secrets
import urllib.parse
from dataclasses import dataclass
from typing import Dict, Optional, Tuple

import requests


@dataclass
class PKCELoginConfig:
    auth0_domain: str
    client_id: str
    redirect_uri: str
    scope: str = "openid profile email"
    audience: Optional[str] = None
    login_hint: Optional[str] = None


@dataclass
class PKCELoginResult:
    authorize_url: str
    state: str
    code_verifier: str


class Auth0PKCEClient:
    def __init__(self, config: PKCELoginConfig):
        self.config = config
        self._issuer = f"https://{config.auth0_domain}"
        self._authorize_endpoint = f"{self._issuer}/authorize"
        self._token_endpoint = f"{self._issuer}/oauth/token"
        self._userinfo_endpoint = f"{self._issuer}/userinfo"

    @staticmethod
    def _base64url_no_padding(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")

    @classmethod
    def _generate_code_verifier(cls) -> str:
        return cls._base64url_no_padding(secrets.token_bytes(32))

    @classmethod
    def _generate_code_challenge(cls, code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        return cls._base64url_no_padding(digest)

    @staticmethod
    def _generate_state() -> str:
        return secrets.token_urlsafe(32)

    def build_authorize_url(self) -> PKCELoginResult:
        code_verifier = self._generate_code_verifier()
        code_challenge = self._generate_code_challenge(code_verifier)
        state = self._generate_state()

        params: Dict[str, str] = {
            "client_id": self.config.client_id,
            "response_type": "code",
            "redirect_uri": self.config.redirect_uri,
            "scope": self.config.scope,
            "state": state,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }
        if self.config.audience:
            params["audience"] = self.config.audience
        if self.config.login_hint:
            params["login_hint"] = self.config.login_hint

        authorize_url = f"{self._authorize_endpoint}?{urllib.parse.urlencode(params)}"
        return PKCELoginResult(authorize_url=authorize_url, state=state, code_verifier=code_verifier)

    def exchange_code_for_tokens(self, code: str, code_verifier: str) -> Dict:
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.config.client_id,
            "code": code,
            "redirect_uri": self.config.redirect_uri,
            "code_verifier": code_verifier,
        }
        response = requests.post(
            self._token_endpoint,
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def fetch_userinfo(self, access_token: str) -> Dict:
        response = requests.get(
            self._userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json()


def create_auth0_pkce_client_from_env() -> Auth0PKCEClient:
    domain = os.environ["AUTH0_DOMAIN"]
    client_id = os.environ["AUTH0_CLIENT_ID"]
    redirect_uri = os.environ["AUTH0_REDIRECT_URI"]
    scope = os.getenv("AUTH0_SCOPE", "openid profile email")
    audience = os.getenv("AUTH0_AUDIENCE") or None
    login_hint = os.getenv("AUTH0_LOGIN_HINT") or None
    return Auth0PKCEClient(
        PKCELoginConfig(
            auth0_domain=domain,
            client_id=client_id,
            redirect_uri=redirect_uri,
            scope=scope,
            audience=audience,
            login_hint=login_hint,
        )
    )
